var n={en:`HR, Sales and Finance want separate release cycles, yet their data is interdependent and one platform team operates everything.`,ua:`HR, Sales і Finance хочуть незалежні релізи, але їхні дані пов’язані, а експлуатацією займається одна команда.`};var t={en:[`Compare modular monolith, split services and external SaaS.`,`Draw data ownership and permissions for your choice.`,`Write ADR with migration cost and payroll consistency risks.`],ua:[`Порівняй модульний моноліт, окремі сервіси та зовнішній SaaS.`,`Намалюй власність даних і права.`,`Напиши ADR із вартістю міграції та ризиками зарплат.`]};var s=[{en:`Sensitive data has one accountable owner.`,ua:`Чутливі дані мають відповідального власника.`},{en:`Integration cannot bypass authorization boundaries.`,ua:`Інтеграції не обходять авторизацію.`}];var i={scenario:n,tasks:t,checks:s};export{s as checks,i as default,n as scenario,t as tasks};